import datetime
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def to_decimal(raw, fallback):
    if raw is None or raw == "":
        return Decimal(fallback)
    try:
        return Decimal(str(raw))
    except InvalidOperation:
        return Decimal(fallback)


def money(value):
    rounded = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return "{:,.2f}".format(rounded)


raw_amount = params.get("amount")
if not isinstance(raw_amount, dict):
    raw_amount = {"amount": raw_amount}
client = params.get("client") or {}
if not isinstance(client, dict):
    client = {}
currency = str(raw_amount.get("currency") or params.get("currency") or "AUD").upper()
gross = to_decimal(raw_amount.get("amount"), "0")
discount_percent = to_decimal(params.get("discount_percent"), "0")
max_discount = to_decimal(params.get("max_discount_percent"), "15")
try:
    valid_days = int(params.get("valid_days") or 14)
except (TypeError, ValueError):
    valid_days = 14

issues = []
if gross <= 0:
    issues.append("The deal amount is missing or zero, so there is nothing to price.")
if discount_percent < 0:
    issues.append("A negative discount is not allowed.")
    discount_percent = Decimal("0")
if discount_percent > max_discount:
    issues.append("The discount of " + str(discount_percent) + "% is above the policy limit of " + str(max_discount) + "%.")

discount_value = gross * discount_percent / Decimal(100)
net_value = gross - discount_value
within_policy = gross > 0 and discount_percent <= max_discount
gross_amount = money(gross)
discount_amount = money(discount_value)
net_amount = money(net_value)
valid_until = (datetime.date.today() + datetime.timedelta(days=valid_days)).isoformat()
prepared_for = str(client.get("name") or client.get("email") or "the client")
summary = currency + " " + net_amount + " after a " + str(discount_percent) + "% discount on " + currency + " " + gross_amount + "; the policy allows up to " + str(max_discount) + "%."
